import React, { Component } from "react";
import { Col, Container, Row } from "react-bootstrap";

export default class ShippingOptions extends Component {
  render() {
    return (
      <div>
        <Container>
          <Row>
            <h3> Shipping Options</h3>
            <Col>
              {" "}
              <input
                type="number"
                id="quantity"
                name="quantity"
                min="1"
                max="5"
              />
            </Col>
            <Col>2 of 2</Col>
          </Row>
        </Container>
      </div>
    );
  }
}
